(31, 'Joker: Điên Có Đôi', 'Joker: Folie a Deux', 'Arthur Fleck bị giam giữ tại Arkham chờ ngày xét xử và tìm thấy tình yêu đích thực của đời mình cùng tri kỷ âm nhạc Harleen Quinzel.', 138, '2026-10-04', '2026-12-30', 'T18', 'Todd Phillips', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/aciP8Km0waTL31IRt5Hih3FkIqL.jpg', 'https://image.tmdb.org/t/p/original/joker2_banner.jpg', 'https://www.youtube.com/watch?v=_OKAwz2NiJs', 'COMING_SOON', NOW(), NOW()),
(32, 'Venom: Kèo Cuối', 'Venom: The Last Dance', 'Eddie Brock và sinh vật cộng sinh Venom bước vào cuộc đào tẩu định mệnh khi bị săn đuổi bởi quân đội Trái Đất và chủng loài ngoài không gian.', 110, '2026-10-25', '2026-12-30', 'T13', 'Kelly Marcel', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/venom3_poster.jpg', 'https://image.tmdb.org/t/p/original/venom3_banner.jpg', 'https://www.youtube.com/watch?v=venom3_trailer', 'COMING_SOON', NOW(), NOW()),
(33, 'Võ Sĩ Giác Đấu II', 'Gladiator II', 'Nhiều năm sau cái chết của Maximus, Lucius Verus bị bắt làm nô lệ và buộc phải bước vào đấu trường La Mã khốc liệt để giành lại tự do.', 150, '2026-11-15', '2026-12-31', 'T18', 'Ridley Scott', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/gladiator2_poster.jpg', 'https://image.tmdb.org/t/p/original/gladiator2_banner.jpg', 'https://www.youtube.com/watch?v=gladiator2_trailer', 'COMING_SOON', NOW(), NOW()),
(34, 'Hành Trình Của Moana 2', 'Moana 2', 'Moana nhận được tiếng gọi bất ngờ từ tổ tiên và cùng Maui dấn thân vào vùng biển xa xôi nguy hiểm vượt ra ngoài đại dương châu Đại Dương.', 100, '2026-11-27', '2027-01-31', 'P', 'David G. Derrick Jr.', 'Lồng tiếng Tiếng Việt', 'Mỹ', 'https://image.tmdb.org/t/p/w500/moana2_poster.jpg', 'https://image.tmdb.org/t/p/original/moana2_banner.jpg', 'https://www.youtube.com/watch?v=moana2_trailer', 'COMING_SOON', NOW(), NOW()),
(35, 'Wicked: Phần 1', 'Wicked: Part One', 'Khám phá tình bạn kỳ lạ giữa Elphaba - Phù thủy xấu xa phương Tây da xanh và Glinda - Phù thủy tốt bụng phương Bắc tại xứ sở Oz.', 160, '2026-11-22', '2027-01-15', 'K', 'Jon M. Chu', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/wicked_poster.jpg', 'https://image.tmdb.org/t/p/original/wicked_banner.jpg', 'https://www.youtube.com/watch?v=wicked_trailer', 'COMING_SOON', NOW(), NOW()),
(36, 'Mufasa: Vua Sư Tử', 'Mufasa: The Lion King', 'Câu chuyện xúc động về thời niên thiếu mồ côi lạc loài của vị vua Mufasa trước khi lên ngôi chúa tể muôn loài tại vùng đất Pride Lands.', 118, '2026-12-20', '2027-02-15', 'P', 'Barry Jenkins', 'Lồng tiếng Tiếng Việt', 'Mỹ', 'https://image.tmdb.org/t/p/w500/mufasa_poster.jpg', 'https://image.tmdb.org/t/p/original/mufasa_banner.jpg', 'https://www.youtube.com/watch?v=mufasa_trailer', 'COMING_SOON', NOW(), NOW()),
(37, 'Nhím Sonic 3', 'Sonic the Hedgehog 3', 'Sonic, Tails và Knuckles đối đầu với kẻ thù mới đầy bí ẩn Shadow the Hedgehog sở hữu sức mạnh hủy diệt và tốc độ siêu việt.', 112, '2026-12-20', '2027-02-15', 'P', 'Jeff Fowler', 'Lồng tiếng Tiếng Việt', 'Mỹ', 'https://image.tmdb.org/t/p/w500/sonic3_poster.jpg', 'https://image.tmdb.org/t/p/original/sonic3_banner.jpg', 'https://www.youtube.com/watch?v=sonic3_trailer', 'COMING_SOON', NOW(), NOW()),
(38, 'Captain America: Thế Giới Mới Dũng Cảm', 'Captain America: Brave New World', 'Sam Wilson tiếp quản danh xưng Đội trưởng Mỹ và vướng vào một âm mưu đảo chính toàn cầu nguy hiểm liên quan đến Tổng thống Thaddeus Ross.', 135, '2027-02-14', '2027-04-30', 'T13', 'Julius Onah', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/cap4_poster.jpg', 'https://image.tmdb.org/t/p/original/cap4_banner.jpg', 'https://www.youtube.com/watch?v=cap4_trailer', 'COMING_SOON', NOW(), NOW()),
(39, 'Superman', 'Superman', 'Khởi đầu kỷ nguyên DC Universe mới dưới bàn tay đạo diễn James Gunn, khắc họa người đàn ông thép Clark Kent cân bằng giữa nguồn gốc Krypton và nhân tính Trái Đất.', 140, '2027-07-11', '2027-09-30', 'T13', 'James Gunn', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/superman_poster.jpg', 'https://image.tmdb.org/t/p/original/superman_banner.jpg', 'https://www.youtube.com/watch?v=superman_trailer', 'COMING_SOON', NOW(), NOW()),
(40, 'Avatar 3: Lửa và Tro Tàn', 'Avatar: Fire and Ash', 'Gia đình Jake Sully chạm trán với Tộc Tro - một phân tộc người Na vi hiếu chiến sinh sống tại các vùng núi lửa hoang sơ đầy chết chóc.', 200, '2027-12-19', '2028-03-31', 'T13', 'James Cameron', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/avatar3_poster.jpg', 'https://image.tmdb.org/t/p/original/avatar3_banner.jpg', 'https://www.youtube.com/watch?v=avatar3_trailer', 'COMING_SOON', NOW(), NOW()),
(41, 'Nhiệm Vụ Bất Khả Thi: Nghiệp Báo Cuối Cùng', 'Mission: Impossible - The Final Reckoning', 'Ethan Hunt cùng đội IMF thực hiện điệp vụ hiểm hóc nhất sự nghiệp nhằm tiêu diệt hoàn toàn thực thể trí tuệ nhân tạo The Entity.', 165, '2027-05-23', '2027-07-31', 'T16', 'Christopher McQuarrie', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/mi8_poster.jpg', 'https://image.tmdb.org/t/p/original/mi8_banner.jpg', 'https://www.youtube.com/watch?v=mi8_trailer', 'COMING_SOON', NOW(), NOW()),
(42, 'Phi Vụ Động Trời 2', 'Zootopia 2', 'Cặp bài trùng thỏ Judy Hopps và cáo Nick Wilde tiếp tục phá án những vụ án bí ẩn chấn động giới cảnh sát đô thị động vật.', 105, '2027-11-26', '2028-01-31', 'P', 'Byron Howard', 'Lồng tiếng Tiếng Việt', 'Mỹ', 'https://image.tmdb.org/t/p/w500/zootopia2_poster.jpg', 'https://image.tmdb.org/t/p/original/zootopia2_banner.jpg', 'https://www.youtube.com/watch?v=zootopia2_trailer', 'COMING_SOON', NOW(), NOW()),
(43, 'Bộ Tứ Siêu Đẳng: Những Bước Đầu', 'The Fantastic Four: First Steps', 'Bộ tứ siêu đẳng bước vào vũ trụ điện ảnh Marvel thời kỳ hoàng kim với trang phục retro-futuristic và kẻ thù khổng lồ Galactus.', 130, '2027-07-25', '2027-09-30', 'T13', 'Matt Shakman', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/f4_poster.jpg', 'https://image.tmdb.org/t/p/original/f4_banner.jpg', 'https://www.youtube.com/watch?v=f4_trailer', 'COMING_SOON', NOW(), NOW()),
(44, 'Công Viên Kỷ Jura: Tái Sinh', 'Jurassic World Rebirth', 'Nhóm chuyên gia đột nhập vào một hòn đảo nhiệt đới hẻo lánh nơi các loài khủng long khổng lồ nhất thời tiền sử đang ngự trị để thu thập mẫu ADN cứu mạng.', 125, '2027-07-02', '2027-09-15', 'T13', 'Gareth Edwards', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/jurassic_poster.jpg', 'https://image.tmdb.org/t/p/original/jurassic_banner.jpg', 'https://www.youtube.com/watch?v=jurassic_trailer', 'COMING_SOON', NOW(), NOW()),
