INSERT INTO movies (id, title, original_title, description, duration_minutes, release_date, end_date, age_rating, director, language, country, poster_url, banner_url, trailer_url, status, created_at, updated_at) VALUES
(1, 'Dune: Hành Tinh Cát - Phần Hai', 'Dune: Part Two', 'Paul Atreides liên minh cùng Chani và người Fremen trên hành trình báo thù những kẻ đã hủy diệt gia tộc anh, đồng thời đối mặt với định mệnh vũ trụ nghiệt ngã.', 166, '2026-03-01', '2026-09-30', 'T16', 'Denis Villeneuve', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/8b8R8l88Qje9dn9OE8PY05Nx2zx.jpg', 'https://image.tmdb.org/t/p/original/xOMo8BRK7PfcJv9JCnx7s520DRq.jpg', 'https://www.youtube.com/watch?v=Way9Dexny3w', 'NOW_SHOWING', NOW(), NOW()),
(2, 'Godzilla x Kong: Đế Chế Mới', 'Godzilla x Kong: The New Empire', 'Hai siêu quái vật huyền thoại phải gác lại mối thù truyền kiếp để hợp sức chống lại một mối hiểm họa khổng lồ đe dọa nuốt chửng Trái Đất rỗng.', 115, '2026-03-29', '2026-09-30', 'T13', 'Adam Wingard', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/bQ2ywkch09oT9GWT4YjhFptOezq.jpg', 'https://image.tmdb.org/t/p/original/qrGtVF3YZvJ6c1XgG9Vp8qH8x.jpg', 'https://www.youtube.com/watch?v=lV1OOlGwExg', 'NOW_SHOWING', NOW(), NOW()),
(3, 'Mai', 'Mai', 'Cuộc đời đầy cay đắng, khát khao được yêu thương của người phụ nữ tên Mai cùng chàng trai đào hoa kém tuổi tên Sâu nơi khu chung cư cũ.', 131, '2026-02-10', '2026-09-30', 'T18', 'Trấn Thành', 'Tiếng Việt', 'Việt Nam', 'https://image.tmdb.org/t/p/w500/yPt3b8eP6e0iYv5e4eY8uM8t4.jpg', 'https://image.tmdb.org/t/p/original/yPt3b8eP6e0iYv5e4eY8uM8t4.jpg', 'https://www.youtube.com/watch?v=cK_dE8Qc0bA', 'NOW_SHOWING', NOW(), NOW()),
(4, 'Kung Fu Panda 4', 'Kung Fu Panda 4', 'Gấu Po nhận trọng trách mới làm Thủ lĩnh tinh thần Thung lũng Bình Yên và phải tìm kiếm một Thần Long Đại Hiệp kế vị trước kẻ thù Tắc Kè Bông xảo quyệt.', 94, '2026-03-08', '2026-09-30', 'P', 'Mike Mitchell', 'Lồng tiếng Tiếng Việt', 'Mỹ', 'https://image.tmdb.org/t/p/w500/kDp1vUBnMpe8ak4rjgl3cLELqjU.jpg', 'https://image.tmdb.org/t/p/original/1XDDXPXGiI8id7MrUxK36ke7gkX.jpg', 'https://www.youtube.com/watch?v=_inKs4eeHiI', 'NOW_SHOWING', NOW(), NOW()),
(5, 'Lật Mặt 7: Một Điều Ước', 'Face Off 7: One Wish', 'Câu chuyện cảm động rơi nước mắt về người mẹ già 73 tuổi cùng 5 người con đã trưởng thành, mỗi người một số phận nơi các vùng miền đất nước.', 138, '2026-04-26', '2026-09-30', 'K', 'Lý Hải', 'Tiếng Việt', 'Việt Nam', 'https://image.tmdb.org/t/p/w500/9baTgUq43mZJ18gT9qFfK5zP5a.jpg', 'https://image.tmdb.org/t/p/original/9baTgUq43mZJ18gT9qFfK5zP5a.jpg', 'https://www.youtube.com/watch?v=1Awe_gH814c', 'NOW_SHOWING', NOW(), NOW()),
(6, 'Oppenheimer', 'Oppenheimer', 'Hành trình nghiên cứu và chế tạo bom nguyên tử đầu tiên trong lịch sử nhân loại của nhà vật lý lý thuyết J. Robert Oppenheimer trong dự án Manhattan.', 180, '2026-01-01', '2026-09-30', 'T18', 'Christopher Nolan', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/8Gxv8gSFCU0XGDykEGv7zR1n2ua.jpg', 'https://image.tmdb.org/t/p/original/fm6KqXpk3M2HVveHwCrBSSBaO0V.jpg', 'https://www.youtube.com/watch?v=uYPbbksJxIg', 'NOW_SHOWING', NOW(), NOW()),
(7, 'Deadpool & Wolverine', 'Deadpool & Wolverine', 'Cặp đôi đối nghịch nhất vũ trụ Marvel bất đắc dĩ bắt tay nhau trong một nhiệm vụ điên rồ giải cứu dòng thời gian và đa vũ trụ.', 127, '2026-07-26', '2026-10-31', 'T18', 'Shawn Levy', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/8cdWjvZQUExUUTzyp4t6EDMubfO.jpg', 'https://image.tmdb.org/t/p/original/yDHYTjA3R0jEjriirbeAnmKp90g.jpg', 'https://www.youtube.com/watch?v=73_1biulkYk', 'NOW_SHOWING', NOW(), NOW()),
(8, 'Kẻ Trộm Mặt Trăng 4', 'Despicable Me 4', 'Gru cùng đại gia đình đối mặt với ác nhân Maxime Le Mal và người bạn gái quyến rũ Valentina, mở màn cuộc đại chiến Minions siêu sức mạnh.', 95, '2026-07-05', '2026-10-15', 'P', 'Chris Renaud', 'Lồng tiếng Tiếng Việt', 'Mỹ', 'https://image.tmdb.org/t/p/w500/wWba3TaojhK7NdycRhoQpsG0FaH.jpg', 'https://image.tmdb.org/t/p/original/lgkFt6tcRTCgqp7tIYF7fAv11oj.jpg', 'https://www.youtube.com/watch?v=qQlr9-rF32A', 'NOW_SHOWING', NOW(), NOW()),
(9, 'Những Mảnh Ghép Cảm Xúc 2', 'Inside Out 2', 'Cô bé Riley bước vào tuổi dậy thì với sự xuất hiện bất ngờ của những cảm xúc mới tinh: Lo Âu, Ganh Tị, Xấu Hổ và Chán Chường.', 96, '2026-06-14', '2026-10-15', 'P', 'Kelsey Mann', 'Lồng tiếng Tiếng Việt', 'Mỹ', 'https://image.tmdb.org/t/p/w500/vpnVM9B6NMmQpWeZvzLvDESb2QY.jpg', 'https://image.tmdb.org/t/p/original/p5ozvmdgsmbWe0H8Xk7uO8e4RTe.jpg', 'https://www.youtube.com/watch?v=LEjhY15eCx0', 'NOW_SHOWING', NOW(), NOW()),
(10, 'Hành Tinh Khỉ: Vương Quốc Mới', 'Kingdom of the Planet of the Apes', 'Nhiều thế hệ sau triều đại của Caesar, một thủ lĩnh khỉ bạo tàn trỗi dậy trong khi chú khỉ trẻ Noa dấn thân vào hành trình định đoạt tương lai.', 145, '2026-05-10', '2026-09-30', 'T13', 'Wes Ball', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/gKkl37BQuKTanygYQG1pyYgLVgf.jpg', 'https://image.tmdb.org/t/p/original/fqvXv6q9quF7Z426X2P4p09e7Fp.jpg', 'https://www.youtube.com/watch?v=XtFI7SNtVpY', 'NOW_SHOWING', NOW(), NOW()),
(11, 'Exhuma: Quật Mộ Trùng Ma', 'Exhuma', 'Hai pháp sư, một thầy phong thủy và một chuyên gia tang lễ hợp lực khai quật một ngôi mộ bí ẩn tại vùng quê hẻo lánh, giải phóng một thế lực tà ác cổ xưa.', 134, '2026-03-15', '2026-09-30', 'T16', 'Jang Jae-hyun', 'Tiếng Hàn (Phụ đề Tiếng Việt)', 'Hàn Quốc', 'https://image.tmdb.org/t/p/w500/kZJeWsLnfeBQL7ffX9zZkC84pQ4.jpg', 'https://image.tmdb.org/t/p/original/5Eip60UDiPLWNmvmWXM2qR84q8F.jpg', 'https://www.youtube.com/watch?v=man4X-Fj6X4', 'NOW_SHOWING', NOW(), NOW()),
(12, 'Furiosa: Câu Chuyện Từ Max Điên', 'Furiosa: A Mad Max Saga', 'Nguồn gốc của nữ chiến binh Furiosa khi cô bị bắt cóc khỏi Vùng Xanh và rơi vào tay Biker Horde do bạo chúa Dementus cầm đầu.', 148, '2026-05-24', '2026-09-30', 'T18', 'George Miller', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Úc', 'https://image.tmdb.org/t/p/w500/iADOJ8Zymht2JPMoy3R7xUMZqaC.jpg', 'https://image.tmdb.org/t/p/original/wNAhuOZ3Zf84jCI5TeKff46ImRi.jpg', 'https://www.youtube.com/watch?v=XJMuhwVlca4', 'NOW_SHOWING', NOW(), NOW()),
(13, 'Vùng Đất Câm Lặng: Ngày Một', 'A Quiet Place: Day One', 'Khám phá ngày thế giới rơi vào tĩnh lặng khi những sinh vật ngoài hành tinh nhạy cảm với âm thanh bắt đầu cuộc xâm lăng tàn khốc New York.', 99, '2026-06-28', '2026-09-30', 'T16', 'Michael Sarnoski', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/yrpPYKijwd9JaUhbpUm9KfBpncs.jpg', 'https://image.tmdb.org/t/p/original/2RVcJbWFmICRDs7E8Udp6zb98UV.jpg', 'https://www.youtube.com/watch?v=YPY7J-flzE8', 'NOW_SHOWING', NOW(), NOW()),
(14, 'Alien: Romulus', 'Alien: Romulus', 'Một nhóm người trẻ khai hoang thuộc địa không gian đụng độ với sinh vật săn mồi kinh hoàng nhất trong vũ trụ tại trạm nghiên cứu bỏ hoang.', 119, '2026-08-16', '2026-10-31', 'T18', 'Fede Alvarez', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/b33nnKl1GSFbao8l3Pgs40um573.jpg', 'https://image.tmdb.org/t/p/original/9SSEUrSqhljBMzRe4aB5Y1e457f.jpg', 'https://www.youtube.com/watch?v=x0XDEhP4MQs', 'NOW_SHOWING', NOW(), NOW()),
(15, 'Thám Tử Conan: Ngôi Sao 5 Cánh 1 Triệu Đô', 'Detective Conan: The Million-dollar Pentagram', 'Cuộc đối đầu kịch tính tại Hakodate giữa Conan, Heiji Hattori và Siêu trộm Kaito Kid xoay quanh thanh kiếm báu thời Mạc Phủ.', 110, '2026-08-02', '2026-10-15', 'T13', 'Chika Nagaoka', 'Lồng tiếng Tiếng Việt', 'Nhật Bản', 'https://image.tmdb.org/t/p/w500/8tU8sN60K0L2k7cO9x8t2wE5J1g.jpg', 'https://image.tmdb.org/t/p/original/8tU8sN60K0L2k7cO9x8t2wE5J1g.jpg', 'https://www.youtube.com/watch?v=conan_trailer', 'NOW_SHOWING', NOW(), NOW()),
(16, 'Spider-Man: Du Hành Vũ Trụ Nhện', 'Spider-Man: Across the Spider-Verse', 'Miles Morales phóng xuyên qua đa vũ trụ để cùng Gwen Stacy đối mặt với Liên minh Nhện hùng mạnh và kẻ thù bí hiểm The Spot.', 140, '2026-01-15', '2026-09-30', 'P', 'Joaquim Dos Santos', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg', 'https://image.tmdb.org/t/p/original/4HodYYKEIsGOdinkGi2Ucz6X9i0.jpg', 'https://www.youtube.com/watch?v=cqGjhVJWtEg', 'NOW_SHOWING', NOW(), NOW()),
(17, 'Avatar: Dòng Chảy Của Nước', 'Avatar: The Way of Water', 'Gia đình Jake Sully rời khỏi rừng rậm để nương náu nơi các bộ tộc sống ở bờ biển Pandora khi người Trái Đất quay trở lại trả thù.', 192, '2026-01-01', '2026-09-30', 'T13', 'James Cameron', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/t6HIqrRAclMCA60NsSmeqe9RmNV.jpg', 'https://image.tmdb.org/t/p/original/s16H6tpK2utvwDtzZ8Qy4qm5Emw.jpg', 'https://www.youtube.com/watch?v=d9MyW72ELq0', 'NOW_SHOWING', NOW(), NOW()),
(18, 'Đất Rừng Phương Nam', 'Song of the South', 'Chuyến phiêu lưu tìm cha đầy gian nan nhưng thấm đẫm nghĩa tình quê hương của cậu bé An cùng nhân dân Nam Bộ thời kháng Pháp.', 134, '2026-01-01', '2026-09-30', 'K', 'Nguyễn Quang Dũng', 'Tiếng Việt', 'Việt Nam', 'https://image.tmdb.org/t/p/w500/uYm7pYcOqM10tY0pY7x6t1qG8P4.jpg', 'https://image.tmdb.org/t/p/original/uYm7pYcOqM10tY0pY7x6t1qG8P4.jpg', 'https://www.youtube.com/watch?v=datrung_trailer', 'NOW_SHOWING', NOW(), NOW()),
(19, 'Nhà Bà Nữ', 'The House of No Man', 'Mâu thuẫn gia đình 3 thế hệ xoay quanh quán bánh canh cua trứ danh cùng những rạn nứt tâm lý giữa cha mẹ và con cái trưởng thành.', 102, '2026-01-01', '2026-09-30', 'T16', 'Trấn Thành', 'Tiếng Việt', 'Việt Nam', 'https://image.tmdb.org/t/p/w500/nhabanu_poster.jpg', 'https://image.tmdb.org/t/p/original/nhabanu_banner.jpg', 'https://www.youtube.com/watch?v=nhabanu_trailer', 'NOW_SHOWING', NOW(), NOW()),
(20, 'Gia Tài Của Ngoại', 'How to Make Millions Before Grandma Dies', 'Chàng thanh niên M bỏ việc để tận tâm chăm sóc người bà mắc ung thư giai đoạn cuối với ý định ban đầu là thừa kế căn nhà bạc triệu.', 127, '2026-06-07', '2026-10-15', 'P', 'Pat Boonnitipat', 'Tiếng Thái (Phụ đề Tiếng Việt)', 'Thái Lan', 'https://image.tmdb.org/t/p/w500/giatai_poster.jpg', 'https://image.tmdb.org/t/p/original/giatai_banner.jpg', 'https://www.youtube.com/watch?v=giatai_trailer', 'NOW_SHOWING', NOW(), NOW()),
(21, 'Ma Da', 'Ma Da', 'Nghề vớt xác trên sông nước miền Tây đối mặt với những hiện tượng tâm linh kỳ quái và lời nguyền oan hồn kéo chân đoạt mạng.', 92, '2026-08-16', '2026-10-31', 'T16', 'Nguyễn Hữu Hoàng', 'Tiếng Việt', 'Việt Nam', 'https://image.tmdb.org/t/p/w500/mada_poster.jpg', 'https://image.tmdb.org/t/p/original/mada_banner.jpg', 'https://www.youtube.com/watch?v=mada_trailer', 'NOW_SHOWING', NOW(), NOW()),
(22, 'Cám', 'Tam Cam: The Dark Tale', 'Dị bản kinh dị đẫm máu xoay quanh số phận của cô Cám với gương mặt dị tật và bí mật đen tối của gia tộc giấu kín suốt ngàn năm.', 122, '2026-09-20', '2026-11-15', 'T18', 'Trần Hữu Tấn', 'Tiếng Việt', 'Việt Nam', 'https://image.tmdb.org/t/p/w500/cam_poster.jpg', 'https://image.tmdb.org/t/p/original/cam_banner.jpg', 'https://www.youtube.com/watch?v=cam_trailer', 'NOW_SHOWING', NOW(), NOW()),
(23, 'Transformers: Một', 'Transformers One', 'Câu chuyện chưa kể về tình anh em thuở hàn vi giữa Orion Pax và D-16 trước khi họ trở thành kẻ thù không đội trời chung Optimus Prime và Megatron.', 104, '2026-09-20', '2026-11-20', 'P', 'Josh Cooley', 'Lồng tiếng Tiếng Việt', 'Mỹ', 'https://image.tmdb.org/t/p/w500/qbkPtOVM5qPa0PFipd8HGxCBBEK.jpg', 'https://image.tmdb.org/t/p/original/hctfG8c60lP9aT1V0b6bVqP2T8e.jpg', 'https://www.youtube.com/watch?v=transformers_trailer', 'NOW_SHOWING', NOW(), NOW()),
(24, 'Vây Hãm: Kẻ Trừng Phạt', 'The Roundup: Punishment', 'Thanh tra quái vật Ma Seok-do đối đầu với một tổ chức tội phạm cờ bạc trực tuyến quy mô quốc tế do tay sát thủ máu lạnh điều hành.', 109, '2026-04-26', '2026-09-30', 'T18', 'Heo Myeong-haeng', 'Tiếng Hàn (Phụ đề Tiếng Việt)', 'Hàn Quốc', 'https://image.tmdb.org/t/p/w500/vayham_poster.jpg', 'https://image.tmdb.org/t/p/original/vayham_banner.jpg', 'https://www.youtube.com/watch?v=vayham_trailer', 'NOW_SHOWING', NOW(), NOW()),
(25, 'Cười 2', 'Smile 2', 'Ngôi sao nhạc pop toàn cầu Skye Riley chuẩn bị cho chuyến lưu diễn thế giới thì liên tiếp gặp phải những ảo giác ma quái rùng rợn không lối thoát.', 127, '2026-10-18', '2026-12-01', 'T18', 'Parker Finn', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/smile2_poster.jpg', 'https://image.tmdb.org/t/p/original/smile2_banner.jpg', 'https://www.youtube.com/watch?v=smile2_trailer', 'NOW_SHOWING', NOW(), NOW()),
(26, 'Twisters: Lốc Xoáy Tử Thần', 'Twisters', 'Một nhóm nhà săn bão trẻ tuổi liều mình đi sâu vào tâm chấn các cơn lốc xoáy khổng lồ chưa từng thấy tại Oklahoma để thử nghiệm công nghệ dập bão.', 122, '2026-07-19', '2026-10-15', 'T13', 'Lee Isaac Chung', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/twisters_poster.jpg', 'https://image.tmdb.org/t/p/original/twisters_banner.jpg', 'https://www.youtube.com/watch?v=twisters_trailer', 'NOW_SHOWING', NOW(), NOW()),
(27, 'Challengers: Những Kẻ Thách Đấu', 'Challengers', 'Mối tình tay ba cuồng nhiệt, ganh đua nghẹt thở trong thế giới quần vợt chuyên nghiệp giữa Tashi Duncan cùng hai tay vợt đỉnh cao.', 131, '2026-05-03', '2026-09-30', 'T18', 'Luca Guadagnino', 'Tiếng Anh (Phụ đề Tiếng Việt)', 'Mỹ', 'https://image.tmdb.org/t/p/w500/challengers_poster.jpg', 'https://image.tmdb.org/t/p/original/challengers_banner.jpg', 'https://www.youtube.com/watch?v=challengers_trailer', 'NOW_SHOWING', NOW(), NOW()),
(28, 'Bố Già', 'Dad, I am Sorry', 'Tình phụ tử sâu nặng giữa người cha nghèo khó Giàu và đứa con trai làm nghề tự do trong con hẻm lao động bình dân Sài Gòn.', 128, '2026-01-01', '2026-09-30', 'T13', 'Vũ Ngọc Đãng, Trấn Thành', 'Tiếng Việt', 'Việt Nam', 'https://image.tmdb.org/t/p/w500/bogia_poster.jpg', 'https://image.tmdb.org/t/p/original/bogia_banner.jpg', 'https://www.youtube.com/watch?v=bogia_trailer', 'NOW_SHOWING', NOW(), NOW()),
(29, 'Quỷ Cẩu', 'A Dog Named Revenge', 'Cái chết bí ẩn của người cha làm nghề mổ chó kéo theo hàng loạt hiện tượng rùng rợn và tai ương giáng xuống cả một gia đình.', 108, '2026-01-01', '2026-09-30', 'T18', 'Lưu Thành Luân', 'Tiếng Việt', 'Việt Nam', 'https://image.tmdb.org/t/p/w500/quycau_poster.jpg', 'https://image.tmdb.org/t/p/original/quycau_banner.jpg', 'https://www.youtube.com/watch?v=quycau_trailer', 'NOW_SHOWING', NOW(), NOW()),
(30, 'Gặp Lại Chị Bầu', 'Meet My Pregnant Sister Again', 'Chàng trai mồ côi Phúc vô tình xuyên không về thập niên 90 và gặp gỡ người mẹ quá cố thời trẻ, khám phá bí mật cuộc đời cô.', 114, '2026-02-10', '2026-09-30', 'K', 'Đoàn Nhất Trung', 'Tiếng Việt', 'Việt Nam', 'https://image.tmdb.org/t/p/w500/chibau_poster.jpg', 'https://image.tmdb.org/t/p/original/chibau_banner.jpg', 'https://www.youtube.com/watch?v=chibau_trailer', 'NOW_SHOWING', NOW(), NOW()),
